Index: index.html
===================================================================
--- index.html	
+++ index.html	
@@ -0,0 +1,324 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8" />
+<meta name="viewport" content="width=device-width, initial-scale=1.0" />
+<title>Call of Duty: Playground Ops — Browser Experiment</title>
+<style>
+  * { box-sizing: border-box; margin: 0; padding: 0; }
+  body {
+    background: #0b0e12; color: #e8e8e8;
+    font-family: "Arial Black", Arial, Helvetica, sans-serif;
+    display: flex; flex-direction: column; align-items: center;
+    min-height: 100vh; padding: 16px;
+  }
+  h1 { font-size: 22px; letter-spacing: 2px; color: #ffd75e; text-transform: uppercase; }
+  h1 small { display: block; font-size: 11px; color: #9aa4b2; letter-spacing: 4px; font-family: Arial, sans-serif; }
+  #wrap { position: relative; margin-top: 12px; }
+  canvas { background: #1a2018; border: 3px solid #3a3a3a; border-radius: 6px; cursor: crosshair; display: block; }
+  #hud {
+    position: absolute; left: 0; right: 0; bottom: 0;
+    display: flex; justify-content: space-between; align-items: flex-end;
+    padding: 10px 14px; pointer-events: none;
+    font-family: Arial, sans-serif;
+  }
+  .panel { background: rgba(0,0,0,.55); border: 1px solid rgba(255,215,94,.4); border-radius: 6px; padding: 6px 12px; }
+  #healthbar { width: 220px; height: 14px; background: #400; border-radius: 7px; overflow: hidden; margin-top: 4px; }
+  #healthfill { height: 100%; width: 100%; background: linear-gradient(90deg,#57ff57,#b6ff57); transition: width .15s; }
+  #overlay {
+    position: absolute; inset: 0; display: flex; flex-direction: column;
+    align-items: center; justify-content: center; text-align: center;
+    background: rgba(0,0,0,.78); border-radius: 6px;
+  }
+  #overlay.hidden { display: none; }
+  #overlay h2 { color: #ffd75e; font-size: 34px; letter-spacing: 3px; }
+  #overlay p { font-family: Arial, sans-serif; color: #cfd6de; margin: 10px 0; max-width: 520px; line-height: 1.5; }
+  button {
+    font-family: inherit; font-size: 16px; letter-spacing: 2px; cursor: pointer;
+    background: #ffd75e; border: none; border-radius: 4px; padding: 10px 28px; margin-top: 8px;
+  }
+  button:hover { background: #ffea9e; }
+  #controls { font-family: Arial, sans-serif; font-size: 13px; color: #9aa4b2; margin-top: 10px; }
+  #controls b { color: #fff; }
+</style>
+</head>
+<body>
+<h1>Call of Duty: Playground Ops <small>browser game experiment — original homage, no affiliated assets</small></h1>
+<div id="wrap">
+  <canvas id="game" width="960" height="600"></canvas>
+  <div id="hud">
+    <div class="panel">
+      <div>HEALTH</div>
+      <div id="healthbar"><div id="healthfill"></div></div>
+      <div id="wave" style="margin-top:4px">WAVE 1 &nbsp;•&nbsp; KILLS 0 &nbsp;•&nbsp; SCORE 0</div>
+    </div>
+    <div class="panel" id="ammo" style="font-size:22px">30 / 120</div>
+  </div>
+  <div id="overlay">
+    <h2 id="title">PLAYGROUND OPS</h2>
+    <p id="desc">WASD move • Mouse aim • Click shoot • <b>R</b> reload • <b>Shift</b> sprint.<br/>Survive endless waves. Health regenerates after 3s without damage — just like CoD.</p>
+    <button id="startBtn">DEPLOY</button>
+  </div>
+</div>
+<div id="controls"><b>WASD</b> move · <b>Mouse</b> aim · <b>Click / Space</b> fire · <b>R</b> reload · <b>Shift</b> sprint · <b>P</b> pause</div>
+
+<script>
+(() => {
+"use strict";
+const canvas = document.getElementById('game');
+const ctx = canvas.getContext('2d');
+const W = canvas.width, H = canvas.height;
+const overlay = document.getElementById('overlay');
+const titleEl = document.getElementById('title');
+const descEl = document.getElementById('desc');
+const startBtn = document.getElementById('startBtn');
+const healthfill = document.getElementById('healthfill');
+const waveEl = document.getElementById('wave');
+const ammoEl = document.getElementById('ammo');
+
+// --- Audio (tiny WebAudio synth, no assets) ---
+let AC = null;
+function audio() { if (!AC) { try { AC = new (window.AudioContext||window.webkitAudioContext)(); } catch(e){} } return AC; }
+function shotSound(enemy) {
+  const ac = audio(); if (!ac) return;
+  const dur = 0.12, buf = ac.createBuffer(1, ac.sampleRate*dur, ac.sampleRate);
+  const d = buf.getChannelData(0);
+  for (let i=0;i<d.length;i++) d[i] = (Math.random()*2-1) * Math.pow(1-i/d.length, 2);
+  const src = ac.createBufferSource(); src.buffer = buf;
+  const f = ac.createBiquadFilter(); f.type='lowpass'; f.frequency.value = enemy?900:2500;
+  const g = ac.createGain(); g.gain.value = enemy?0.15:0.3;
+  src.connect(f); f.connect(g); g.connect(ac.destination); src.start();
+}
+function reloadSound(){ const ac=audio(); if(!ac) return; const o=ac.createOscillator(),g=ac.createGain(); o.type='square'; o.frequency.value=300; g.gain.value=0.08; o.connect(g); g.connect(ac.destination); o.start(); o.stop(ac.currentTime+0.08); }
+function hitSound(){ const ac=audio(); if(!ac) return; const o=ac.createOscillator(),g=ac.createGain(); o.type='sine'; o.frequency.value=1200; g.gain.value=0.12; o.connect(g); g.connect(ac.destination); o.start(); o.stop(ac.currentTime+0.05); }
+
+// --- Covers / map obstacles ---
+const covers = [
+  {x:120,y:120,w:140,h:24},{x:700,y:120,w:140,h:24},
+  {x:120,y:456,w:140,h:24},{x:700,y:456,w:140,h:24},
+  {x:430,y:200,w:100,h:30},{x:430,y:370,w:100,h:30},
+  {x:300,y:285,w:40,h:60},{x:620,y:285,w:40,h:60},
+];
+function collidesCover(x,y,r){
+  for (const c of covers) {
+    const nx = Math.max(c.x, Math.min(x, c.x+c.w));
+    const ny = Math.max(c.y, Math.min(y, c.y+c.h));
+    if ((x-nx)**2 + (y-ny)**2 < r*r) return c;
+  }
+  return null;
+}
+function bulletHitsCover(x,y){
+  for (const c of covers) if (x>c.x&&x<c.x+c.w&&y>c.y&&y<c.y+c.h) return true;
+  return false;
+}
+
+// --- State ---
+let state = 'menu', paused = false;
+let player, bullets, ebullets, enemies, particles, hitmarkers;
+let wave, kills, score, mouse = {x:W/2,y:H/2,down:false};
+let keys = {};
+let lastTime = 0, lastDamage = 0, shake = 0;
+
+function reset(){
+  player = { x:W/2, y:H/2+120, r:14, hp:100, maxHp:100, speed:210, angle: -Math.PI/2,
+             mag:30, magSize:30, reserve:120, reloading:false, reloadT:0, fireCd:0 };
+  bullets=[]; ebullets=[]; enemies=[]; particles=[]; hitmarkers=[];
+  wave=1; kills=0; score=0; shake=0; lastDamage=-9999;
+  spawnWave(wave);
+}
+function spawnWave(n){
+  const count = 3 + n*2;
+  for (let i=0;i<count;i++){
+    const edge = i%4;
+    let x,y;
+    if (edge===0){x=Math.random()*W;y=20;} else if(edge===1){x=Math.random()*W;y=H-20;}
+    else if(edge===2){x=20;y=Math.random()*H;} else {x=W-20;y=Math.random()*H;}
+    const hp = 30 + n*8;
+    enemies.push({ x, y, r:13, hp, maxHp:hp, speed: 60+Math.min(140, n*10+Math.random()*40),
+                   fireCd: 1+Math.random()*2, dmg: 6+n });
+  }
+}
+
+function startGame(){ reset(); state='play'; paused=false; overlay.classList.add('hidden'); lastTime=performance.now(); requestAnimationFrame(loop); }
+function gameOver(){
+  state='over';
+  titleEl.textContent='K.I.A. — GAME OVER';
+  descEl.innerHTML=`You survived to <b>WAVE ${wave}</b> with <b>${kills} kills</b> and <b>${score} points</b>.<br/>Click REDEPLOY to go again, soldier.`;
+  startBtn.textContent='REDEPLOY';
+  overlay.classList.remove('hidden');
+}
+
+function spawnParticles(x,y,color,n=10){
+  for(let i=0;i<n;i++) particles.push({x,y,vx:(Math.random()-0.5)*300,vy:(Math.random()-0.5)*300,life:0.4,color});
+}
+
+// --- Input ---
+window.addEventListener('keydown', e => {
+  keys[e.key.toLowerCase()]=true;
+  if (e.key.toLowerCase()==='r') startReload();
+  if (e.key.toLowerCase()==='p' && state==='play') paused=!paused;
+  if (e.key===' '){ mouse.down=true; e.preventDefault(); }
+});
+window.addEventListener('keyup', e => { keys[e.key.toLowerCase()]=false; if(e.key===' ') mouse.down=false; });
+canvas.addEventListener('mousemove', e => { const r=canvas.getBoundingClientRect(); mouse.x=(e.clientX-r.left)*(W/r.width); mouse.y=(e.clientY-r.top)*(H/r.height); });
+canvas.addEventListener('mousedown', ()=>{ audio(); mouse.down=true; });
+window.addEventListener('mouseup', ()=>{ mouse.down=false; });
+startBtn.addEventListener('click', ()=>{ audio(); startGame(); });
+
+function startReload(){
+  if (!player || state!=='play' || player.reloading || player.mag===player.magSize || player.reserve<=0) return;
+  player.reloading=true; player.reloadT=1.1; reloadSound();
+}
+
+// --- Update ---
+function update(dt, now){
+  // player move
+  let dx=0,dy=0;
+  if(keys['w']||keys['arrowup'])dy-=1; if(keys['s']||keys['arrowdown'])dy+=1;
+  if(keys['a']||keys['arrowleft'])dx-=1; if(keys['d']||keys['arrowright'])dx+=1;
+  const sprint=(keys['shift'])?1.5:1;
+  if(dx||dy){ const l=Math.hypot(dx,dy); dx/=l; dy/=l;
+    const nx=player.x+dx*player.speed*sprint*dt, ny=player.y+dy*player.speed*sprint*dt;
+    if(!collidesCover(nx,player.y,player.r)) player.x=Math.max(player.r,Math.min(W-player.r,nx));
+    if(!collidesCover(player.x,ny,player.r)) player.y=Math.max(player.r,Math.min(H-player.r,ny));
+  }
+  player.angle=Math.atan2(mouse.y-player.y, mouse.x-player.x);
+
+  // reload + fire
+  if(player.reloading){ player.reloadT-=dt; if(player.reloadT<=0){ const need=player.magSize-player.mag, take=Math.min(need,player.reserve); player.mag+=take; player.reserve-=take; player.reloading=false; } }
+  player.fireCd-=dt;
+  if(mouse.down && !player.reloading && player.fireCd<=0 && state==='play' && !paused){
+    if(player.mag>0){ player.mag--; player.fireCd=0.13;
+      const a=player.angle+(Math.random()-0.5)*0.05;
+      bullets.push({x:player.x+Math.cos(a)*22, y:player.y+Math.sin(a)*22, vx:Math.cos(a)*700, vy:Math.sin(a)*700, life:1.2});
+      shotSound(false); shake=Math.min(6,shake+2);
+      spawnParticles(player.x+Math.cos(a)*26, player.y+Math.sin(a)*26, '#ffdd55', 3);
+    } else startReload();
+  }
+
+  // health regen (CoD style)
+  if(now-lastDamage>3000 && player.hp<player.maxHp) player.hp=Math.min(player.maxHp, player.hp+25*dt);
+
+  // enemies
+  for(const e of enemies){
+    const dxp=player.x-e.x, dyp=player.y-e.y, d=Math.hypot(dxp,dyp)||1;
+    let mx=dxp/d, my=dyp/d;
+    // keep some distance, strafe
+    const want=220;
+    let mvx=mx, mvy=my;
+    if(d<want){ mvx=-mx*0.5; mvy=-my*0.5; } // back off if too close
+    const nx=e.x+mvx*e.speed*dt, ny=e.y+mvy*e.speed*dt;
+    if(!collidesCover(nx,e.y,e.r)) e.x=Math.max(e.r,Math.min(W-e.r,nx));
+    if(!collidesCover(e.x,ny,e.r)) e.y=Math.max(e.r,Math.min(H-e.r,ny));
+    e.fireCd-=dt;
+    if(e.fireCd<=0 && d<520){
+      // line of sight blocked by cover?
+      let blocked=false;
+      for(let t=0;t<1;t+=0.05){ if(bulletHitsCover(e.x+(player.x-e.x)*t, e.y+(player.y-e.y)*t)){blocked=true;break;} }
+      if(!blocked){ const a=Math.atan2(dyp,dxp)+(Math.random()-0.5)*0.15;
+        ebullets.push({x:e.x,y:e.y,vx:Math.cos(a)*320,vy:Math.sin(a)*320,life:2,dmg:e.dmg});
+        shotSound(true); e.fireCd=1.2+Math.random()*1.5;
+      } else e.fireCd=0.3;
+    }
+    // touch damage
+    if(d < e.r+player.r){ player.hp-=20*dt; lastDamage=now; }
+  }
+
+  // player bullets vs enemies
+  for(let i=bullets.length-1;i>=0;i--){
+    const b=bullets[i]; b.x+=b.vx*dt; b.y+=b.vy*dt; b.life-=dt;
+    let dead = b.life<=0||b.x<0||b.x>W||b.y<0||b.y>H||bulletHitsCover(b.x,b.y);
+    if(!dead) for(let j=enemies.length-1;j>=0;j--){
+      const e=enemies[j];
+      if((b.x-e.x)**2+(b.y-e.y)**2 < (e.r+3)**2){
+        e.hp-=25; hitSound(); hitmarkers.push({x:e.x,y:e.y,life:0.25});
+        spawnParticles(b.x,b.y,'#ff5555',5);
+        if(e.hp<=0){ enemies.splice(j,1); kills++; score+=100+wave*10; spawnParticles(e.x,e.y,'#ff3333',16); }
+        dead=true; break;
+      }
+    }
+    if(dead) bullets.splice(i,1);
+  }
+  // enemy bullets vs player
+  for(let i=ebullets.length-1;i>=0;i--){
+    const b=ebullets[i]; b.x+=b.vx*dt; b.y+=b.vy*dt; b.life-=dt;
+    let dead=b.life<=0||bulletHitsCover(b.x,b.y);
+    if(!dead && (b.x-player.x)**2+(b.y-player.y)**2 < (player.r+3)**2){
+      player.hp-=b.dmg; lastDamage=now; shake=Math.min(8,shake+3);
+      spawnParticles(player.x,player.y,'#ff0000',6); dead=true;
+    }
+    if(dead) ebullets.splice(i,1);
+  }
+  particles=particles.filter(p=>{ p.x+=p.vx*dt; p.y+=p.vy*dt; p.life-=dt; return p.life>0; });
+  hitmarkers=hitmarkers.filter(h=>(h.life-=dt)>0);
+
+  if(player.hp<=0){ player.hp=0; gameOver(); }
+  else if(enemies.length===0){ wave++; score+=250; // bonus + small ammo resupply
+    player.reserve+=30; spawnWave(wave); }
+
+  // HUD
+  healthfill.style.width=(player.hp/player.maxHp*100)+'%';
+  healthfill.style.background=player.hp>60?'linear-gradient(90deg,#57ff57,#b6ff57)':player.hp>30?'linear-gradient(90deg,#ffaa00,#ffdd55)':'linear-gradient(90deg,#ff2222,#ff7777)';
+  waveEl.textContent=`WAVE ${wave}  •  KILLS ${kills}  •  SCORE ${score}`;
+  ammoEl.textContent=(player.reloading?'RELOADING…':`${player.mag} / ${player.reserve}`);
+}
+
+// --- Draw ---
+function draw(){
+  ctx.save();
+  if(shake>0){ ctx.translate((Math.random()-0.5)*shake,(Math.random()-0.5)*shake); shake*=0.88; if(shake<0.3)shake=0; }
+  // ground
+  ctx.fillStyle='#232a20'; ctx.fillRect(-10,-10,W+20,H+20);
+  ctx.strokeStyle='rgba(255,255,255,0.05)'; ctx.lineWidth=1;
+  for(let x=0;x<W;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}
+  for(let y=0;y<H;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
+  // covers
+  for(const c of covers){ ctx.fillStyle='#4a4438'; ctx.fillRect(c.x,c.y,c.w,c.h);
+    ctx.fillStyle='#5d5646'; ctx.fillRect(c.x,c.y,c.w,6); ctx.strokeStyle='#221e15'; ctx.strokeRect(c.x,c.y,c.w,c.h); }
+  // bullets
+  ctx.fillStyle='#ffe97a'; for(const b of bullets){ ctx.beginPath(); ctx.arc(b.x,b.y,3,0,7); ctx.fill(); }
+  ctx.fillStyle='#ff5555'; for(const b of ebullets){ ctx.beginPath(); ctx.arc(b.x,b.y,3,0,7); ctx.fill(); }
+  // enemies
+  for(const e of enemies){
+    ctx.fillStyle='#a33327'; ctx.beginPath(); ctx.arc(e.x,e.y,e.r,0,7); ctx.fill();
+    ctx.fillStyle='#5c1a12'; ctx.beginPath(); ctx.arc(e.x,e.y,e.r-5,0,7); ctx.fill();
+    const a=Math.atan2(player.y-e.y,player.x-e.x);
+    ctx.strokeStyle='#111'; ctx.lineWidth=5; ctx.beginPath(); ctx.moveTo(e.x,e.y); ctx.lineTo(e.x+Math.cos(a)*20,e.y+Math.sin(a)*20); ctx.stroke();
+    ctx.fillStyle='#000'; ctx.fillRect(e.x-14,e.y-e.r-10,28,5);
+    ctx.fillStyle='#f00'; ctx.fillRect(e.x-14,e.y-e.r-10,28*(e.hp/e.maxHp),5);
+  }
+  // player
+  if(player){
+    ctx.save(); ctx.translate(player.x,player.y); ctx.rotate(player.angle);
+    ctx.fillStyle='#2f6b2f'; ctx.beginPath(); ctx.arc(0,0,player.r,0,7); ctx.fill();
+    ctx.fillStyle='#1d421d'; ctx.beginPath(); ctx.arc(0,0,player.r-5,0,7); ctx.fill();
+    ctx.fillStyle='#222'; ctx.fillRect(8,-3,22,6);
+    ctx.restore();
+  }
+  // particles / hitmarkers
+  for(const p of particles){ ctx.globalAlpha=Math.max(0,p.life*2.5); ctx.fillStyle=p.color; ctx.fillRect(p.x-2,p.y-2,4,4); }
+  ctx.globalAlpha=1;
+  ctx.strokeStyle='#fff'; ctx.lineWidth=2;
+  for(const h of hitmarkers){ const s=8*(h.life/0.25); ctx.beginPath();
+    ctx.moveTo(h.x-s,h.y-s);ctx.lineTo(h.x-s+4,h.y-s+4); ctx.moveTo(h.x+s,h.y-s);ctx.lineTo(h.x+s-4,h.y-s+4);
+    ctx.moveTo(h.x-s,h.y+s);ctx.lineTo(h.x-s+4,h.y+s-4); ctx.moveTo(h.x+s,h.y+s);ctx.lineTo(h.x+s-4,h.y+s-4); ctx.stroke(); }
+  // damage vignette
+  if(player && player.hp<50){ ctx.fillStyle=`rgba(255,0,0,${(50-player.hp)/50*0.25})`; ctx.fillRect(0,0,W,H); }
+  ctx.restore();
+  if(paused){ ctx.fillStyle='rgba(0,0,0,.6)'; ctx.fillRect(0,0,W,H); ctx.fillStyle='#ffd75e'; ctx.font='bold 40px Arial'; ctx.textAlign='center'; ctx.fillText('PAUSED',W/2,H/2); }
+}
+
+function loop(now){
+  if(state!=='play') return;
+  const dt=Math.min(0.033,(now-lastTime)/1000); lastTime=now;
+  if(!paused) { update(dt, now); draw(); }
+  else draw();
+  requestAnimationFrame(loop);
+}
+// menu backdrop
+reset(); draw();
+window.__game = { reset, spawnWave, startReload, getState: () => ({state, wave, kills, score, player}) };
+})();
+</script>
+</body>
+</html>

