python3 -c "
import re
html = open('index.html').read()
js = re.search(r'<script>(.*)</script>', html, re.S).group(1)
# stub RAF to not loop forever: run one manual test harness
harness = '''
// ---- stubs ----
global.window = global;
global.performance = { now: () => 0 };
global.requestAnimationFrame = () => {};
const els = {};
function mkEl(){ return { style:{}, textContent:'', innerHTML:'', classList:{add(){},remove(){}}, addEventListener(){}, getContext:()=> new Proxy({}, {get:(t,k)=> (k==\"createBuffer\"?()=>({getChannelData:()=>[]}) : ()=>{}) }) }; }
global.document = { getElementById:(id)=> els[id] || (els[id]=mkEl()) };
window.addEventListener=()=>{}; window.AudioContext=undefined;
global.__game=null;
''' + js + '''
// ---- tests ----
const s = window.__game.getState();
console.log('state:', s.state, 'wave:', s.wave, 'enemies:', s.player ? 'player ok' : 'no player');
window.__game.reset();
const s2 = window.__game.getState();
console.log('after reset wave:', s2.wave, 'player hp:', s2.player.hp, 'mag:', s2.player.mag);
window.__game.spawnWave(5);
console.log('spawnWave(5) ok');
window.__game.startReload();
console.log('startReload ok, reloading:', window.__game.getState().player.reloading);
console.log('ALL SMOKE TESTS PASSED');
'''
open('/tmp/smoke.js','w').write(harness)
" && node /tmp/smoke.js

