const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    args: ['--no-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage({ viewport: { width: 1100, height: 800 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/index.html');
  await page.waitForTimeout(800);
  await page.screenshot({ path: '/tmp/shot/menu.png' });
  // start game
  await page.click('#startBtn');
  await page.waitForTimeout(1200);
  // move + aim + fire like a player
  await page.mouse.move(700, 250);
  await page.keyboard.down('w');
  await page.mouse.down();
  await page.waitForTimeout(900);
  await page.mouse.up();
  await page.keyboard.up('w');
  await page.keyboard.press('r');
  await page.waitForTimeout(700);
  await page.mouse.move(300, 500);
  await page.mouse.down();
  await page.waitForTimeout(900);
  await page.mouse.up();
  await page.screenshot({ path: '/tmp/shot/gameplay.png' });
  const st = await page.evaluate(() => window.__game ? window.__game.getState() : null);
  console.log('STATE:', JSON.stringify({ state: st && st.state, wave: st && st.wave, kills: st && st.kills, score: st && st.score, enemies: st && st.enemyCount, hp: st && st.player && Math.round(st.player.hp), mag: st && st.player && st.player.mag }));
  console.log('ERRORS:', errors.length ? errors.join(' | ') : 'none');
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

