function drawWeapon(){
  // compact bottom-center rifle viewmodel with recoil + ADS centering
  const cx=W/2, by=H+4-recoil*8-adsF*14;
  ctx.save(); ctx.translate(cx,by);
  const sway=Math.sin(timeSec*2)*1.5;
  const s=0.62; // viewmodel scale — keep it compact, never a screen-dominating bar
  ctx.scale(s,s);
  ctx.translate(sway*0.3,0);
  // stock + receiver
  ctx.fillStyle='#171410'; ctx.fillRect(-11,-78+recoil*6,22,78);          // receiver
  ctx.fillStyle='#26221b'; ctx.fillRect(-9,-96+recoil*6,18,20);           // top rail
  ctx.fillStyle='#0c0b09'; ctx.fillRect(-3,-112+recoil*6,6,18);           // barrel tip
  ctx.fillStyle='#4a3820'; ctx.fillRect(-13,-58+recoil*6,26,20);          // wooden foregrip
  ctx.fillStyle='#33291a'; ctx.fillRect(-8,-38+recoil*6,16,14);           // magazine
  // front + rear sights
  ctx.fillStyle='#000'; ctx.fillRect(-2,-118+recoil*6,4,6);
  if(adsF>0.5){ ctx.strokeStyle='#000'; ctx.lineWidth=3; ctx.strokeRect(-13,-94+recoil*6,26,14); }
  // hands
  ctx.fillStyle='#c9a06a'; ctx.fillRect(-17,-62+recoil*6,10,13); ctx.fillRect(7,-80+recoil*6,10,13);
  // muzzle flash (compact star)
  if(muzzle>0){
    const f=muzzle*(0.7+Math.random()*0.5);
    ctx.fillStyle='rgba(255,220,100,'+(0.9*f)+')';
    const tipY=-112+recoil*6;
    ctx.beginPath();
    ctx.moveTo(-3,tipY); ctx.lineTo(-13,tipY-26*f); ctx.lineTo(0,tipY-34*f);
    ctx.lineTo(13,tipY-26*f); ctx.lineTo(3,tipY);
    ctx.fill();
  }
  ctx.restore();
}

input.oldString:
function drawWeapon(){
  // bottom-center rifle viewmodel with recoil + ADS centering
  const cx=W/2, by=H+6-recoil*14-adsF*26;
  ctx.save(); ctx.translate(cx,by);
  const sway=Math.sin(timeSec*2)*2;
  // gun body
  ctx.fillStyle='#151310';
  ctx.fillRect(-14+sway*0.3,-120+recoil*8,28,120);           // receiver
  ctx.fillStyle='#23211c'; ctx.fillRect(-11+sway*0.3,-150+recoil*8,22,34); // barrel shroud
  ctx.fillStyle='#0c0b09'; ctx.fillRect(-4+sway*0.3,-168+recoil*8,8,20);   // barrel tip
  ctx.fillStyle='#3a2f1d'; ctx.fillRect(-16+sway*0.3,-96+recoil*8,32,26);  // wood grip
  // rear sight when ADS
  if(adsF>0.5){ ctx.strokeStyle='#000'; ctx.lineWidth=3; ctx.strokeRect(-16,-140,32,20); }
  // hands
  ctx.fillStyle='#c9a06a'; ctx.fillRect(-20+sway*0.3,-104+recoil*8,12,16); ctx.fillRect(8+sway*0.3,-128+recoil*8,12,16);
  // muzzle flash
  if(muzzle>0){
    const f=muzzle*(0.7+Math.random()*0.5);
    ctx.fillStyle='rgba(255,220,100,'+(0.9*f)+')';
    ctx.beginPath();
    ctx.moveTo(-4+sway*0.3,-168+recoil*8);
    ctx.lineTo(-22+sway*0.3,-196*f-168+recoil*8+196*(1-f)*0.2);
    ctx.lineTo(0+sway*0.3,-214*f-168+recoil*8+214*(1-f)*0.2);
    ctx.lineTo(22+sway*0.3,-196*f-168+recoil*8+196*(1-f)*0.2);
    ctx.lineTo(4+sway*0.3,-168+recoil*8);
    ctx.fill();
  }
  ctx.restore();
}

