input.content:
const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    args: ['--no-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage({ viewport: { width: 1100, height: 800 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/index.html');
  await page.waitForTimeout(400);
  await page.click('#startBtn');
  await page.waitForTimeout(400);
  async function toPage(x, y) {
    return await page.evaluate(([wx, wy]) => {
      const r = document.getElementById('game').getBoundingClientRect();
      return { x: r.left + wx / 960 * r.width, y: r.top + wy / 600 * r.height };
    }, [x, y]);
  }
  await page.mouse.down({ button: 'left' });
  let st, t = 0, dir = true;
  while (t < 90000) {
    st = await page.evaluate(() => window.__game.getState());
    if (!st || st.state !== 'play' || st.wave >= 2) break;
    // strafe to open firing angles around cover
    if (dir) { await page.keyboard.down('a'); await page.keyboard.up('d'); }
    else { await page.keyboard.down('d'); await page.keyboard.up('a'); }
    if (st.enemies.length) {
      const p = st.player;
      let best = st.enemies[0], bd = 1e18;
      for (const e of st.enemies) { const d = (e.x - p.x) ** 2 + (e.y - p.y) ** 2; if (d < bd) { bd = d; best = e; } }
      const pt = await toPage(best.x, best.y);
      await page.mouse.move(pt.x, pt.y);
    }
    await page.waitForTimeout(300);
    t += 300;
    if (Math.floor(t / 2000) % 2 === 0) dir = !dir;
    const s2 = await page.evaluate(() => window.__game.getState());
    if (s2 && s2.player.mag === 0 && !s2.player.reloading) { await page.keyboard.press('r'); }
  }
  await page.keyboard.up('a'); await page.keyboard.up('d');
  await page.mouse.up({ button: 'left' });
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/shot/final.png' });
  st = await page.evaluate(() => window.__game.getState());
  console.log('RESULT:', JSON.stringify({ state: st.state, wave: st.wave, kills: st.kills, score: st.score, enemies: st.enemyCount, hp: Math.round(st.player.hp), mag: st.player.mag, reserve: st.player.reserve }));
  console.log('WAVECHECK:', st.wave >= 2 ? 'PASS' : 'FAIL');
  console.log('ERRORS:', errors.length ? errors.join(' | ') : 'none');
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

